export function runTopic(topicId: string, input: D00Input): D00Output {
  if (input === null || typeof input !== "object" || Array.isArray(input)) throw new TypeError("input must be an object");
  const match = /^D00-(F\d{2})-A(\d{2})$/.exec(topicId);
  if (!match || !families[match[1]]) throw new RangeError(`unsupported D00 topic id: ${topicId}`);
  const index = Number(match[2]);
  if (index < 1 || index > 10) throw new RangeError(`unsupported topic number: ${index}`);
  return families[match[1]](index, input);
}
